import {deviceRuntime,resourceUse,installStatus,hostDataPorts,poolProtections,poolUsable} from './device-runtime.js';
import {productProfile} from './product-profiles.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=(key,label,value='',type='text')=>`<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0"':''}></label>`;
const select=(key,label,items,value)=>`<label>${label}<select name="${key}">${items.map(x=>{const [k,t]=Array.isArray(x)?x:[x,x];return `<option value="${esc(k)}" ${String(value)===String(k)?'selected':''}>${esc(t)}</option>`;}).join('')}</select></label>`;
const check=(key,label,value=true)=>`<label class="pg-check"><input name="${key}" type="checkbox" ${value?'checked':''}>${label}</label>`;
const form=(op,body,label='Apply changes')=>`<form data-runtime-form="${op}"><div class="pg-grid">${body}</div><button type="submit">${label}</button></form>`;
const table=(heads,rows)=>`<div class="runtime-table"><table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}">No records yet. Create the first one below.</td></tr>`}</tbody></table></div>`;
const vals=x=>Object.values(x||{});
export function runtimePages(n){return [...(['server','gpu'].includes(n.type)?[['os-install','Install OS'],['host-network','Host network'],['virtualization','Virtual machines'],['virtual-network','Virtual networking'],['datastores','Datastores'],['services','Server services']]:[]),...(n.type==='storage'?[['volumes','Pools & volumes'],['storage-hosts','Host access'],...(['powerstore','powerscale','storeonce'].includes(productProfile(n).family)?[['shares','File services']]:[]),...(productProfile(n).family==='objectscale'?[['buckets','Object buckets']]:[])]:[]),...(n.type==='firewall'?[['fw-interfaces','Network / Interfaces'],['fw-routes','Network / Static routes'],['fw-addresses','Policy / Address objects'],['fw-policies','Policy / Firewall policies']]:[]),['hardware','Hardware & health'],['activity','Tasks & logs'],['maintenance','Maintenance']];}
export function runtimeContent(n,page,nodes,network){const r=deviceRuntime(n),use=resourceUse(n),dataPorts=n.ports.map((p,i)=>[i,p]).filter(([,p])=>!p.service&&p.medium==='Ethernet'),opts=dataPorts.map(([i,p])=>[i,p.name+' · '+p.speed+'G']),e=n.net.enterprise;
 if(page==='os-install'){const st=installStatus(n);return `<p>Mount the installer through the iDRAC / iLO virtual console and deploy a host OS. The installer runs for a few seconds; the host must stay powered or the installation fails. A hypervisor has its own management interface after installation.</p><p>Current OS: <strong>${esc(r.os||'Not installed')}</strong> · Installer: <strong>${esc(st.reason)}</strong></p>`+form('os',select('os','Installation image',['Linux','Windows Server','VMware ESXi','KVM','Hyper-V'],r.install?.os||r.os)+select('raid','Boot storage',['RAID 1 boot','RAID 10','HBA / passthrough'],r.raid),st.state==='failed'?'Run installer again':'Install selected OS');}
 if(page==='host-network')return '<p>This is the host OS data network (for host-level services). The dedicated iDRAC / iLO management port and address stay separate and never carry host data VLANs. The selected NIC becomes an 802.1Q uplink; the switch port must carry this VLAN.</p>'+form('host-network',select('port','Host data NIC',hostDataPorts(n).map(([i,p])=>[i,p.name+' · '+p.speed+'G']),r.hostPort??hostDataPorts(n)[0]?.[0])+input('ip','Host data IP',r.hostIP||'10.10.50.10')+input('prefix','Prefix length',r.hostPrefix,'number')+input('vlan','Data VLAN',r.hostVlan,'number')+input('gateway','Gateway',r.gateway||'10.10.50.1')+input('dns','DNS',r.dns||'10.10.70.1')+input('ntp','NTP',r.ntp||'10.10.70.1'));
 if(page==='virtual-network')return `<p>Port groups do not change your physical switch configuration. Trunks must carry the selected VLAN. Enter multiple uplink indices for link failover.</p>${table(['Port group','VLAN','Uplinks','MTU'],vals(r.portgroups).map(x=>[x.id,x.vlan,x.uplinks.map(i=>n.ports[i]?.name).join(', '),x.mtu]))}`+form('portgroup',input('id','Port group','Servers')+input('vlan','VLAN ID',50,'number')+select('uplink','Primary physical uplink',opts)+input('uplinks','Optional uplink indices, separated by commas','')+select('mtu','MTU',[1500,9000],1500),'Create / update port group');
 if(page==='virtualization')return `<p>${esc(r.hypervisor||'Install a hypervisor to begin')} · Allocated ${use.cpu}/${r.cpu} vCPU · ${use.memory}/${r.memory} GiB memory · ${use.disk} GiB disk</p>${table(['VM','OS','vCPU','RAM GiB','Disk GiB','Network','Power / path'],vals(r.vms).map(v=>[v.id,v.os,v.cpu,v.memory,v.disk,v.network,network.vmState(n,v).reason]))}`+form('vm',input('id','VM name','WEB-01')+select('os','Guest OS',['Linux','Windows Server'])+input('cpu','vCPUs',2,'number')+input('memory','RAM GiB',4,'number')+input('disk','Disk GiB',40,'number')+select('datastore','Datastore',Object.keys(r.datastores))+select('network','Port group',Object.keys(r.portgroups))+input('ip','Guest IP','10.10.50.11')+input('prefix','Prefix',24,'number')+input('gateway','Gateway','10.10.50.1')+input('dns','DNS','10.10.70.1'),'Create / update VM')+form('vm-power',select('id','Virtual machine',Object.keys(r.vms))+select('action','Action',[['start','Power on'],['stop','Power off'],['delete','Delete powered-off VM']]),'Apply VM action');
 if(page==='datastores'){const seen=network.hostVolumes?network.hostVolumes(n):[];return table(['Datastore','Source','Capacity GiB','State'],vals(r.datastores).map(x=>{if(x.kind==='local')return [x.id,'Local disks',x.sizeGiB,'Local'];const a=network.volumeAccess?.(nodes.find(y=>y.id===x.array),x.volume,n);return [x.id,x.array+' / '+x.volume,x.sizeGiB,a?a.reason:'—'];}))+'<h3>Storage devices seen by this host (rescan)</h3>'+table(['Array / volume','GiB','Access','Paths / reason'],seen.map(x=>[x.array+' / '+x.volume,x.sizeGiB,x.access||'—',x.reason]))+`<p>Configure the host storage initiator in Lifecycle / Host OS, register and map the host on the array, then connect the FC / iSCSI / NVMe-TCP A and B paths. A volume appears here only when masking, initiator and at least one data path work.</p>`+form('datastore',input('id','Datastore name','Shared-01')+select('array','Storage array',nodes.filter(x=>x.active!==false&&x.type==='storage').map(x=>[x.id,x.id+' · '+x.model]))+input('volume','Mapped volume name','VOL-01'),'Rescan & mount datastore');}
 if(page==='services')return `<p>Create a service on this host or a VM. A working data path, DNS record and firewall policy are required for employee access. Test from an office PC.</p>${table(['Target','Service','Listener','State','Requests'],[[r,...[]],...vals(r.vms).map(v=>[v])].flatMap(([host])=>vals(host.services).map(s=>[host.id||'Host',s.id,s.ip+':'+s.port,s.running?'Running':'Stopped',s.requests||0])))}`+form('service',select('vm','Run on',[['','Host operating system'],...vals(r.vms).map(x=>[x.id,x.id])])+input('id','Service name','intranet')+select('kind','Service type',['web','DNS','DHCP','NTP','SMB','NFS','database','monitoring','backup','syslog'])+select('engine','Web engine',['Nginx','Apache','IIS'])+input('name','DNS hostname','intranet.company.test')+input('port','Listening port',443,'number')+input('groups','Allowed groups','company')+check('running','Service running')+check('firewall','Allow listener through host firewall')+`<label>Website content<textarea name="content">Welcome to the company intranet.</textarea></label>`,'Install / update service');
 if(page==='volumes'){const prot=poolProtections(n);return `<p>Raw drive capacity ${vals(r.pools).reduce((s,x)=>s+x.sizeGiB,0)}/${r.capacityGiB} GiB assigned to pools. Usable capacity depends on the pool protection. Configure array data ports (path A/B) in Storage / Hosts / Volumes; management access alone does not present a volume.</p>${table(['Pool','Raw GiB','Protection','Usable GiB','Allocated GiB'],vals(r.pools).map(x=>[x.id,x.sizeGiB,x.protection,poolUsable(x),vals(r.volumes).filter(v=>v.pool===x.id).reduce((s,v)=>s+v.sizeGiB,0)]))}`+form('pool',input('id','Pool name','POOL-01')+input('sizeGiB','Raw drive capacity GiB',16384,'number')+select('protection','Protection',prot),'Create / update pool')+table(['Volume','Pool','GiB','Provisioning','Protocol','Mapped to','Access'],vals(r.volumes).map(x=>[x.id,x.pool,x.sizeGiB,x.thin?'Thin':'Thick',x.protocol,x.group?'Group '+x.group:x.host||'Unmapped',x.access||'read-write']))+form('volume',input('id','Volume name','VOL-01')+select('pool','Pool',Object.keys(r.pools))+input('sizeGiB','Volume GiB',500,'number')+select('protocol','Protocol',productProfile(n).protocols)+select('host','Map to host',[['','— none —'],...Object.keys(r.hosts).map(x=>[x,x])])+select('group','or host group',[['','— none —'],...Object.keys(r.hostGroups||{}).map(x=>[x,x])])+select('access','Host access',['read-write','read-only'])+check('thin','Thin provisioning'),'Create / update volume or mapping')+form('volume-resize',select('id','Volume',Object.keys(r.volumes))+input('sizeGiB','New size GiB (grow only)',1000,'number'),'Expand volume')+form('delete',select('table','Record type',[['volumes','Volume (unmap first)'],['pools','Pool (empty)'],['hostGroups','Host group'],['hosts','Registered host']])+input('id','Record name',''),'Delete record');}
 if(page==='storage-hosts'){const acc=network.arrayVolumes?network.arrayVolumes(n):[];return table(['Host','Initiator','Transport'],vals(r.hosts).map(x=>[x.id,x.initiator,x.protocol||'—']))+form('host-register',select('id','Installed host',nodes.filter(x=>x.active!==false&&['server','gpu'].includes(x.type)).map(x=>[x.id,x.id+' · '+x.model]))+input('initiator','IQN / NQN / WWPN'),'Register host')+table(['Host group','Members'],vals(r.hostGroups).map(x=>[x.id,x.hosts.join(', ')]))+form('host-group',input('id','Host group','CLUSTER-01')+input('hosts','Registered hosts (comma separated)',Object.keys(r.hosts).join(',')),'Create / update host group')+'<h3>Host access and data paths</h3>'+table(['Volume','Host','State','Reason'],acc.map(x=>[x.volume,x.host||'—',x.state,x.reason]))+'<p>Copy the initiator from the server’s Lifecycle / Host OS page. Host registration does not create FC zones or connect physical paths. Two paths through one switch are one failure domain.</p>';}
 if(page==='shares')return table(['Share','Protocol','Data IP','Read groups','Write groups'],vals(r.shares).map(x=>[x.id,x.protocol,x.ip,x.read,x.write]))+form('share',input('id','Share name','finance')+select('protocol','Protocol',['SMB','NFS'])+input('ip','NAS data IP','10.10.50.20')+input('vlan','Data VLAN',50,'number')+input('quota','Quota GiB',100,'number')+input('read','Read groups','finance,executive')+input('write','Write groups','finance')+input('subnets','NFS client subnets','10.10.20.0/24'),'Create / update share');
 if(page==='buckets')return table(['Bucket','Quota GiB','Retention days','Objects'],vals(r.buckets).map(x=>[x.id,x.quota,x.retention||0,Object.keys(x.objects).length]))+form('bucket',input('id','Bucket name','company-data')+input('quota','Quota GiB',1000,'number')+input('retention','Retention days',30,'number'),'Create bucket');
 if(page==='fw-interfaces')return table(['Interface','IP','Role','Admin','Link'],dataPorts.map(([,p])=>[p.name,p.cfg.ip||'Unassigned',p.cfg.role||'',p.cfg.admin?'Up':'Down',p.link&&!p.link.unplugged&&!p.link.disabled?'Up':'No link']))+form('fw-interface',select('index','Interface',opts)+input('ip','IPv4','10.10.50.1')+input('prefix','Prefix',24,'number')+input('alias','Alias','LAN')+select('role','Role',['lan','wan','dmz'])+check('admin','Enable interface'),'Apply interface');
 if(page==='fw-routes')return table(['ID','Destination','Gateway','Interface'],e.routes.map(x=>[x.id,x.dst,x.gateway,x.device]))+form('fw-route',input('id','Route ID',1,'number')+input('dst','Destination','0.0.0.0/0')+input('gateway','Gateway',n.net.ispContract?.gateway||'203.0.113.1')+select('device','Interface',dataPorts.map(([,p])=>p.name)),'Apply route');
 if(page==='fw-addresses')return table(['Object','Subnet'],vals(e.addresses).map(x=>[x.name,x.subnet]))+form('fw-address',input('name','Object name','Server_Network')+input('subnet','Subnet / prefix','10.10.50.0/24'),'Save address object');
 if(page==='fw-policies')return `<p>Rules are evaluated from top to bottom. An unmatched flow is denied. Changes here and in the Fortinet-style CLI use the same policy list.</p>${table(['ID','Name','Ingress → Egress','Source → Destination','Service','Action','NAT','Enabled'],e.policies.map(x=>[x.id,x.name,x.srcintf+' → '+x.dstintf,(x.srcaddr||'all')+' → '+(x.dstaddr||'all'),x.service||'ALL',x.action,x.nat?'Yes':'No',x.enabled?'Yes':'No']))}`+form('fw-policy',input('id','Policy ID',1,'number')+input('name','Name','LAN-to-WAN')+select('srcintf','Incoming interface',[...dataPorts.map(([,p])=>p.name),...(e.interfaces||[]).map(x=>x.name)])+select('dstintf','Outgoing interface',[...dataPorts.map(([,p])=>p.name),...(e.interfaces||[]).map(x=>x.name)])+select('srcaddr','Source address',['all',...Object.keys(e.addresses||{})])+select('dstaddr','Destination address',['all',...Object.keys(e.addresses||{})])+select('service','Service',['ALL','HTTP','HTTPS','SSH','DNS','SMB','NFS','ICMP'])+select('action','Action',['accept','deny'])+check('nat','Source NAT')+check('enabled','Enable policy'),'Apply policy')+form('fw-move',input('id','Policy ID',1,'number')+select('direction','Move',['up','down']),'Move policy');
 if(page==='hardware')return `<h3>${esc(n.model)}</h3>${table(['Component','State'],[['Power',network.localStatus(n).reason],['PSU A',n.physical?.power[0]||(!n.physical?'Factory A':'Disconnected')],['PSU B',n.physical?.power[1]||(!n.physical?'Factory B':'Disconnected')],['CPU allocation',use.cpu+' / '+r.cpu],['Memory allocation',use.memory+' / '+r.memory+' GiB'],['Boot mode',r.boot],['Operating system',r.os||'Not installed'],['Disk layout',r.raid||'Not configured'],['Hardware fault',n.physical?.fault||'None']])}${table(['Port','Medium','Speed','Status'],n.ports.filter(p=>!p.service).map(p=>[p.name,p.medium,p.speed+'G',p.cfg.admin?p.link&&!p.link.unplugged?'Connected':'No cable':'Shutdown']))}`;
 if(page==='activity')return table(['Time','Task','State'],r.jobs.map(x=>[new Date(x.at).toLocaleTimeString(),x.message,x.state]))+table(['Time','Log'],e.logs.slice(0,30).map(x=>[new Date(x.at).toLocaleTimeString(),x.message]));
 if(page==='maintenance')return '<p>Configuration checkpoints preserve this device’s operational settings. Full campaign saves remain under host control.</p>'+form('checkpoint','','Save device checkpoint')+form('restore','','Restore device checkpoint')+(storage(n)?form('snapshot','','Create storage snapshot')+table(['Snapshot','Created'],r.snapshots.map(x=>[x.id,new Date(x.at).toLocaleString()])):'')+(['server','gpu'].includes(n.type)?form('maintenance',check('enabled','Maintenance mode',r.maintenance),'Apply maintenance mode'):'');
 return null;
}
function storage(n){return n.type==='storage';}
export function bindRuntimeUI(container,n,submit,refresh){for(const f of container.querySelectorAll('[data-runtime-form]'))f.onsubmit=async ev=>{ev.preventDefault();const v={};for(const el of f.elements)if(el.name)v[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;if(v.uplinks==='')delete v.uplinks;const op=f.dataset.runtimeForm;let action={type:'device-op',op,value:v};if(op==='vm-power')v.on=v.action==='start';if(op.startsWith('fw-')){action={type:'enterprise',op:{'fw-route':'route','fw-address':'address','fw-policy':'policy','fw-move':'move-policy'}[op],value:v};if(op==='fw-interface'){const results=[];results.push(await submit({type:'enterprise',op:'interface-address',index:+v.index,ip:v.ip,prefix:v.prefix}));if(results[0]?.startsWith('Applied')){results.push(await submit({type:'cli-state',op:'interface',index:+v.index,value:{alias:v.alias,role:v.role}}));results.push(await submit({type:'port',index:+v.index,value:{admin:v.admin}}));}refresh(results.join('\n'));return;}}if(['restore'].includes(op)&&!confirm('Restore this device checkpoint? Current device configuration will be replaced.'))return;try{refresh(await submit(action));}catch(e){refresh(e.message);}}}
